  "wp.message.26a6374fbf59": "Nie udało się uruchomić dodatku Pixflow. Sprawdź zgodność wtyczek Pixflow i odśwież stronę. Pozostałe funkcje mogą nadal być dostępne.",
  "wp.message.ca7714cffbcc": "Aktywuj Pro",
  "wp.message.197c83a2f752": "Przywróć narzędzia premium dzięki dodatkowi Pro. Licencja, treści i zapisane ustawienia pozostaną zachowane. Jeśli używano uwierzytelniania dwuskładnikowego Bricks, włącz je ponownie w ustawieniach po aktywacji Pro.",
  "wp.message.2ffdcbc380ea": "Twórz w ulubionym kreatorze. Dodaj do pracy adnotacje, obsługę głosu, systemy projektowe i generowanie obrazów.",
  "wp.message.40ed1102964b": "Sprawdź okres próbny Pro",
  "wp.message.e9cccd3ef5fc": "Nie udało się zapisać odrzucenia. Spróbuj ponownie.",
  "wp.message.1372089fb797": "Zamknij baner Pixflow Pro",
  "wp.message.5e3ba715018d": "Pobierz Pro",
  "wp.message.fb2e6d87b44c": "Więcej możliwości z Pixflow Design Pro",
  "wp.message.9934717ca744": "Odśwież tę stronę i spróbuj ponownie.",
  "wp.message.7c78f9990490": "Rozpocznij 7-dniowy okres próbny Pro",
  "wp.message.f89b4dcf2c2e": "Wypróbuj Pro przez 7 dni",
  "wp.message.69ecce9deb2d": "Nie możesz odrzucić tego powiadomienia.",
  "wp.message.927384e7eed8": "Twój plan Pixflow obejmuje Pro",
  "wp.message.64585a3a39ef": "[%s] Zresetowano uwierzytelnianie dwuskładnikowe",
  "wp.message.97c3ac935cc2": "[%s] Twój kod weryfikacyjny",
  "wp.message.b075b6e113fc": "10 minut",
  "wp.message.8bbe8944007a": "Uwierzytelnianie dwuskładnikowe",
  "wp.message.c2bf03beb4f6": "Konfiguracja uwierzytelniania dwuskładnikowego",
  "wp.message.3170543ce47c": "5 minut",
  "wp.message.0d1fa0dfcc9e": "Kod 6-cyfrowy",
  "wp.message.8b6693be283d": "Panel konta",
  "wp.message.107a3671eb84": "Kolor aktywnego/ukończonego kroku",
  "wp.message.47d932f4c02a": "Kolor numeru aktywnego/ukończonego kroku",
  "wp.message.73dbcf028ec6": "Dodaj drugą metodę weryfikacji, aby chronić konto.",
  "wp.message.529da8588051": "Do zakończenia logowania wymagana jest dodatkowa weryfikacja.",
  "wp.message.6b49000156c3": "Administratorzy mogą użyć tego awaryjnego resetowania, gdy użytkownik utracił wszystkie metody uwierzytelniania i kody odzyskiwania.",
  "wp.message.4ea44caf5d6e": "Po formularzu",
  "wp.message.1be05927766c": "Administrator usunął uwierzytelnianie dwuskładnikowe z Twojego konta. Jeśli nie oczekiwano tej zmiany, zresetuj hasło i natychmiast skontaktuj się z administratorem witryny.",
  "wp.message.bd4a7c92a53f": "Okno uwierzytelniania/e-maila/klucza dostępu",
  "wp.message.09a12ace273f": "Aplikacja uwierzytelniająca",
  "wp.message.a4c801f3d189": "Aplikacja uwierzytelniająca jest gotowa",
  "wp.message.9fd5a3f4f23e": "Konfiguracja aplikacji uwierzytelniającej jest wyłączona dla tej witryny.",
  "wp.message.7258165188b4": "Opis aplikacji uwierzytelniającej",
  "wp.message.7cb96fa5a704": "Podgląd kodu QR aplikacji uwierzytelniającej",
  "wp.message.838557924a5c": "Kopia zapasowa",
  "wp.message.216f00eada6a": "Przed formularzem",
  "wp.message.9e2b8fcf9a19": "Symbol zastępczy zablokowanej treści",
  "wp.message.745c19fce0bf": "Symbol zastępczy zablokowanej treści",
  "wp.message.de4aeff9ee43": "Typografia tekstu głównego",
  "wp.message.45e9870097b1": "Tylko w kreatorze. Przypnij wybrany podgląd, aby pozostał otwarty podczas stylizowania innych elementów.",
  "wp.message.c3d4759d35d0": "Podgląd w kreatorze",
  "wp.message.5be164b5cb70": "Nie możesz zeskanować? Wprowadź ten klucz konfiguracji ręcznie:",
  "wp.message.91cfaf3e7a2c": "Anuluj i wróć",
  "wp.message.3b72859f271e": "Tekst przycisku anulowania",
