  "ui.mediaStarter.image1.title": "Portret redakcyjny",
  "ui.mediaStarter.image1.tag": "Portret",
  "ui.mediaStarter.image1.prompt": "Zbliżenie w stylu portretu redakcyjnego młodego dyrektora kreatywnego przed trzydziestką, miękkie naturalne światło przez wysokie okna studia, ciepła neutralna paleta (kremowy, szarobrązowy, delikatna czerń), obiektyw 85mm f/1.8 z małą głębią ostrości, przenikliwe spojrzenie w obiektyw, subtelne ziarno filmu, naturalny wygląd bez makijażu.",
  "ui.mediaStarter.image2.title": "Główne zdjęcie produktu",
  "ui.mediaStarter.image2.tag": "E-commerce",
  "ui.mediaStarter.image2.prompt": "Ekskluzywne zdjęcie pojedynczego matowego ceramicznego kubka do kawy na ciepłym kremowym papierowym tle. Twarde światło konturowe z lewego górnego rogu, delikatny wydłużony cień w prawo i w dół, lekka para nad kubkiem. Kwadratowy kadr, centralna kompozycja, miejsce u góry na nagłówek, bez rekwizytów i dłoni.",
  "ui.mediaStarter.image3.title": "Płaska ilustracja",
  "ui.mediaStarter.image3.tag": "Ilustracja",
  "ui.mediaStarter.image3.prompt": "Płaska ilustracja wektorowa przytulnego kącika czytelniczego przy deszczowym oknie — geometryczne kształty, oszczędna paleta pięciu kolorów (kremowy, terakota, głęboki morski, palona sjena, delikatna czerń), cienkie linie 1.5px, bez gradientów i tekstur, miękkie cienie tylko pod fotelem na pierwszym planie.",
  "ui.mediaStarter.video1.title": "Prezentacja produktu",
  "ui.mediaStarter.video1.tag": "Filmowy",
  "ui.mediaStarter.video1.prompt": "5-sekundowa prezentacja produktu: minimalistyczny ekskluzywny flakon kosmetyku na czystej kremowej powierzchni kamiennej, miękkie światło z lewej strony kamery, powolny najazd, subtelna zmiana ostrości z nakrętki na etykietę, oszczędny ruch, bez napisów i ludzi w kadrze.",
  "ui.mediaStarter.video2.title": "Zbliżenie na lampion",
  "ui.mediaStarter.video2.tag": "Nastrój",
  "ui.mediaStarter.video2.prompt": "6-sekundowe filmowe zbliżenie młodej kobiety trzymającej świecący papierowy lampion w mglistym sosnowym lesie podczas złotej godziny. Mała głębia ostrości na oczach, delikatny najazd kamery, drobinki unoszące się w ciepłej smudze światła, bez dialogu, tylko odgłosy lasu.",
  "ui.mediaStarter.video3.title": "Drift na neonowej ulicy",
  "ui.mediaStarter.video3.tag": "Akcja",
  "ui.mediaStarter.video3.prompt": "5-sekundowe ujęcie śledzące nocny wyścig uliczny w neonowym cyberpunkowym zaułku Hongkongu. Niska kamera podąża za matowoczarnym autem sportowym driftującym na ciasnym zakręcie, rozmycie ruchu kół, flary od zbliżających się neonów, mokry asfalt odbijający światła, bez tekstu na ekranie.",
  "ui.mediaStarter.hyperframes1.title": "Odsłonięcie przez lupę",
  "ui.mediaStarter.hyperframes1.tag": "HTML-in-canvas",
  "ui.mediaStarter.hyperframes1.prompt": "Stwórz 5-sekundową kompozycję z jedną linią pogrubionego tekstu ozdobnego na czystym płótnie. Animuj okrągłą lupę przesuwającą się od lewej do prawej, z subtelnym załamaniem szkła zniekształcającym litery pod nią. Użyj HyperFrames html-in-canvas: przechwyć DOM tekstu i nałóż shader soczewki przez przebieg w stylu vfx-liquid-glass. Tekst w czystym CSS, szkło jako warstwa WebGL.",
  "ui.mediaStarter.hyperframes2.title": "Scena terminala CRT",
  "ui.mediaStarter.hyperframes2.tag": "Efekty retro",
  "ui.mediaStarter.hyperframes2.prompt": "Stwórz kompozycję ekranu CRT: ciemne płótno, tekst terminala o stałej szerokości wpisujący `npx hyperframes init my-video`, następnie `claude` uruchamiane z poleceniem 'Add a CRT effect using HTML-in-canvas'. Nałóż przez html-in-canvas na żywy DOM subtelny shader wypukłości, linie skanowania, lekką aberrację chromatyczną i miękką poświatę luminoforu. Tekst pozostaje prawdziwym CSS, ostrym przed etapem shadera.",
  "ui.mediaStarter.hyperframes3.title": "Rozpad glitch",
  "ui.mediaStarter.hyperframes3.tag": "Glitch",
  "ui.mediaStarter.hyperframes3.prompt": "Zbuduj 6-sekundową kompozycję z głównym nagłówkiem i jednoliniowym podtytułem na ciemnym płótnie, która przechodzi w mocny cyfrowy glitch: rozdzielenie kanałów RGB, poziome pasma przesunięć, krótkie zacięcie klatek i czysty powrót na końcu. Przechwyć żywy DOM przez html-in-canvas i nałóż efekt glitch, zachowując tekst jako prawdziwy CSS pod shaderem.",
  "ui.mediaStarter.audio1.title": "Narracja marki",
  "ui.mediaStarter.audio1.tag": "Mowa",
  "ui.mediaStarter.audio1.prompt": "30-sekundowa ciepła narracja do filmu premierowego produktu — pewna siebie, lecz swobodna, w średnim tempie, z krótką pauzą po nazwie marki. Tekst: 'Three years in the making. One simple promise. Meet [product name] — the way work was supposed to feel.' Po angielsku, neutralny akcent północnoamerykański.",
  "ui.mediaStarter.audio2.title": "Narracja wprowadzająca",
  "ui.mediaStarter.audio2.tag": "Mowa",
  "ui.mediaStarter.audio2.prompt": "20-sekundowa przyjazna narracja na ekran pierwszego uruchomienia aplikacji mobilnej. Uspokajający, pogodny ton, tempo wystarczająco spokojne, by brzmieć uważnie, ale nie jak odczytywany scenariusz. Tekst: „Witaj w Loop. Przygotujmy Twoją przestrzeń — trzy szybkie pytania i gotowe. Wszystko możesz później zmienić”.",
  "ui.mediaStarter.audio3.title": "Czytanie fragmentu opowieści",
  "ui.mediaStarter.audio3.tag": "Mowa",
  "ui.mediaStarter.audio3.prompt": "45-sekundowe filmowe odczytanie początkowego fragmentu opowieści. Niski, wyważony głos z oddechem między zdaniami, nieco intymne brzmienie blisko mikrofonu. Tekst: „Miasto śpi po kawałku. Neon migocze nad ladą z ramenem. Po drugiej stronie alei świeci okno — jedyne jeszcze rozświetlone po tej stronie północy”.",
  "ui.finalWorkspace.72ed7e2a11": "Próbki rodzin fontów",
