  "ui.seoAudit.aClientReportCanPredateSeveral_d76aee45": "Raport klienta może pochodzić przed kilkoma audytami. Tylko informacja „Ostatni rozpoczęty audyt, który się zakończył” identyfikuje poprzedni audyt. Użyj aktualnego planu działania, aby przedstawić rekomendacje. Zachowaj raport i okresy audytów oddzielnie. Poprzednie komentarze zawierają wcześniejsze wskazówki, a nie wiążące się z tym pomiary: mogą odnosić się również do starszych raportów. Użyj datowanych danych weryfikacyjnych dla zakończonej pracy. Brak lub nieodpowiedni audyt nie rozwiązuje problemu.",
