  "ui.seoAudit.boundedFiveWordShingleSimilarityOf_1fc8d930": "Ograniczona podobność tekstu głównego do pięciu słów, z wyłączeniem aliasów i różnych deklarowanych języków. Samo podobieństwo nie jest powodem do przepisywania.",
