  "ui.seoAudit.browserCoverageObservedObservedViewportSamples_c9c88985": "Zakres przeglądarek: {observed} – obserwacja próbek widoku; {unavailable} – niedostępne. Najnowsza próbka dla każdej strony i widoku. Ograniczone obserwacje DOM, nie obejmujące pełnego zakresu JavaScript, wizualna kontrola pikseli, pomiary użytkowników lub zweryfikowane naprawy.",
