  "ui.seoAudit.browserSelectionSelectedOfEligibleEligible_66bfffef": "Wybór przeglądarki: Strony z kategorii {selected} i {eligible}, które są dostępne w ramach szablonów/struktur {represented} i {families}. Wybór nie zakończył się pomyślną weryfikacją. Strony, które nie zostały wybrane, pozostają niezveryfikowane przez przeglądarkę; ich indywidualne wyniki HTML są zachowywane.",
