  "ui.seoAudit.reviewThesePagesTogetherKeepLegitimate_1d5fd748": "Przeanalizujcie te strony wspólnie. Zachowajcie spójne sformułowania i canonicalne aliasy. Zmieniajcie metadane lub treść tylko wtedy, gdy strony służą różnym celom i zmiana przynosi korzyści użytkownikom.",
