  "ui.seoAudit.sectionIdsInCompleteStaticHtml_ffb834de": "Identyfikatory sekcji w pełnym, statycznym kodzie HTML. Identyfikatory w dokumentach zależnych od JavaScript lub w niekompletnym kodzie nie zostały zweryfikowane.",
