  "ui.seoAudit.thisCheckNeedsMoreThanTen_6648ef0b": "Ta kontrola wymaga sprawdzenia co najmniej dziesięciu nowych celów. Przeprowadź nową kontrolę, aby zweryfikować całą grupę.",
  "ui.seoAudit.twoAnonymousGzipNegotiatedRequestsFor_083df39d": "Dwie anonimowe żądania negocjowane za pomocą gzip, obejmujące do trzech stron. Sygnały trafienia w pamięci podręcznej i zweryfikowany gzip to pomiary, a nie wskaźniki prędkości.",
